begin;
do $$
declare own uuid:=gen_random_uuid(); inviter uuid:=gen_random_uuid(); friend uuid:=gen_random_uuid(); stranger uuid:=gen_random_uuid(); b uuid; b2 uuid; code text; slug text:='referral-qa-'||substr(own::text,1,8); config jsonb; dash jsonb; claim jsonb; n integer; signup_friend uuid:=gen_random_uuid(); invalid_friend uuid:=gen_random_uuid();
begin
 insert into auth.users(id,aud,role,email,email_confirmed_at,created_at,updated_at) select u,'authenticated','authenticated','customer-ref-qa-'||u||'@example.invalid',now(),now(),now() from unnest(array[own,inviter,friend,stranger]) u;
 config:='{"programEnabled":true,"pointsPerVisit":50,"pointsPerHundredSpent":10,"rewards":[{"id":"ref-qa","title":"QA referral voucher","requiredPoints":200,"isActive":true,"rewardType":"flat_discount","discountValue":100}]}';
 insert into public.studioflow_accounts(user_id,draft) values(own,jsonb_build_object('profile',jsonb_build_object('businessName','Referral QA'),'loyaltyConfig',config));
 insert into public.studioflow_websites(owner_id,slug,content) values(own,slug,jsonb_build_object('profile',jsonb_build_object('businessName','Referral QA'),'loyaltyConfig',config));
 perform set_config('request.jwt.claim.sub',inviter::text,true);execute 'set local role authenticated';
 code:=public.studioflow_android_referral();
 if not public.studioflow_customer_validate_ref(lower(code)) then raise exception 'FAIL validation';end if;
 begin perform public.studioflow_customer_claim_ref(code);raise exception 'FAIL self-referral accepted';exception when raise_exception then if sqlerrm='FAIL self-referral accepted' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',friend::text,true);
 if public.studioflow_customer_claim_ref(code)<>'saved' or public.studioflow_customer_claim_ref(code)<>'already_saved' then raise exception 'FAIL attribution idempotency';end if;
 begin perform public.studioflow_customer_claim_ref('INVALIDCODE');raise exception 'FAIL invalid accepted';exception when raise_exception then if sqlerrm='FAIL invalid accepted' then raise;end if;end;
 begin execute 'select count(*) from public.studioflow_customer_referrals';raise exception 'FAIL direct identity read';exception when insufficient_privilege then null;end;
 begin execute 'update public.studioflow_customer_referrals set points=200';raise exception 'FAIL direct points mutation';exception when insufficient_privilege then null;end;
 execute 'reset role';
 insert into public.studioflow_bookings(owner_id,customer_id,stylist_id,starts_at,ends_at,status,payload) values(own,friend,'qa',now()-interval '3 days',now()-interval '3 days'+interval '30 minutes','confirmed','{"serviceName":"QA visit","servicePrice":1000,"amountPaid":250,"paymentStatus":"paid_deposit"}') returning id into b;
 if (select sum(points) from public.studioflow_customer_referrals where inviter_id=inviter) is distinct from 0 then raise exception 'FAIL awarded before completion';end if;
 perform set_config('request.jwt.claim.sub',friend::text,true);execute 'set local role authenticated';
 begin perform public.studioflow_update_booking(b,'completed');raise exception 'FAIL customer completed booking';exception when raise_exception then if sqlerrm='FAIL customer completed booking' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',own::text,true);
 perform public.studioflow_update_booking(b,'completed');
 execute 'reset role';
 if (select points from public.studioflow_customer_referrals where invitee_id=friend) is distinct from 200 then raise exception 'FAIL award';end if;
 insert into public.studioflow_bookings(owner_id,customer_id,stylist_id,starts_at,ends_at,status,payload) values(own,friend,'qa',now()-interval '2 days',now()-interval '2 days'+interval '30 minutes','confirmed','{"servicePrice":1000,"amountPaid":250}') returning id into b2;
 update public.studioflow_bookings set status='completed' where id=b2;
 if (select sum(points) from public.studioflow_customer_referrals where inviter_id=inviter) is distinct from 200 then raise exception 'FAIL repeat bonus';end if;
 perform set_config('request.jwt.claim.sub',inviter::text,true);execute 'set local role authenticated';
 dash:=public.studioflow_customer_rewards_dashboard();
 if (select (v->>'points')::integer from jsonb_array_elements(dash->'wallets') v where v->>'slug'=slug) is distinct from 200 then raise exception 'FAIL referral wallet';end if;
 if not exists(select 1 from jsonb_array_elements(dash->'ledger') v where v->>'type'='referral' and (v->>'points')::int=200) then raise exception 'FAIL referral ledger';end if;
 if (public.studioflow_customer_referral_summary()->>'qualified')::int is distinct from 1 then raise exception 'FAIL referral counts';end if;
 claim:=public.studioflow_customer_redeem_reward(slug,'ref-qa',gen_random_uuid());
 if not (claim ? 'code') then raise exception 'FAIL referral redemption';end if;
 dash:=public.studioflow_android_rewards();
 if (select (v->>'points')::integer from jsonb_array_elements(dash) v where v->>'slug'=slug) is distinct from 0 then raise exception 'FAIL header balance sync';end if;
 perform set_config('request.jwt.claim.sub',stranger::text,true);
 if (public.studioflow_customer_referral_summary()->>'joined')::int is distinct from 0 then raise exception 'FAIL private stats';end if;
 if jsonb_array_length(public.studioflow_customer_rewards_dashboard()->'ledger') is distinct from 0 then raise exception 'FAIL private ledger';end if;
 perform public.studioflow_customer_claim_ref(code);
 execute 'reset role';
 insert into public.studioflow_bookings(owner_id,customer_id,stylist_id,starts_at,ends_at,status,payload) values(own,stranger,'qa',now()-interval '1 day',now()-interval '1 day'+interval '30 minutes','confirmed','{"demo":true,"servicePrice":0,"amountPaid":0}') returning id into b2;
 update public.studioflow_bookings set status='completed' where id=b2;
 if (select points from public.studioflow_customer_referrals where invitee_id=stranger) is distinct from 0 then raise exception 'FAIL demo awarded';end if;
 insert into auth.users(id,aud,role,email,email_confirmed_at,created_at,updated_at,raw_user_meta_data) values(signup_friend,'authenticated','authenticated','customer-ref-qa-'||signup_friend||'@example.invalid',now(),now(),now(),jsonb_build_object('customer_referral_code',code,'full_name','Invited QA Friend','date_of_birth','1995-04-20','whatsapp_number','+919876543210'));
 if not exists(select 1 from public.studioflow_customer_referrals where invitee_id=signup_friend and inviter_id=inviter) then raise exception 'FAIL cross-device signup attribution';end if;
 insert into auth.users(id,aud,role,email,created_at,updated_at,raw_user_meta_data) values(invalid_friend,'authenticated','authenticated','customer-ref-qa-'||invalid_friend||'@example.invalid',now(),now(),'{"customer_referral_code":"INVALIDCODE","date_of_birth":"1995-04-20","whatsapp_number":"+919876543210"}');
 if exists(select 1 from public.studioflow_customer_referrals where invitee_id=invalid_friend) then raise exception 'FAIL invalid signup attribution';end if;
 perform set_config('request.jwt.claim.sub',inviter::text,true);execute 'set local role authenticated';
 dash:=public.studioflow_customer_referral_members(0);
 if not exists(select 1 from jsonb_array_elements(dash->'members') m where m->>'name'='Invited QA Friend' and m->>'status'='joined') then raise exception 'FAIL invited profile visibility';end if;
 if (public.studioflow_customer_referral_summary()->>'joined')::int is distinct from 3 then raise exception 'FAIL signup count';end if;
 if dash::text like '%@example.invalid%' or dash::text like '%phone%' or dash::text like '%customer_id%' then raise exception 'FAIL referral member privacy';end if;
 perform set_config('request.jwt.claim.sub',stranger::text,true);
 if jsonb_array_length(public.studioflow_customer_referral_members(0)->'members') is distinct from 0 then raise exception 'FAIL cross inviter visibility';end if;
 execute 'reset role';
 raise notice 'PASS: code validation, self/invalid guards, attribution idempotency, no direct identity/points access, owner-only completion, first paid completion +200, duplicate guard, shared wallet/header/ledger, voucher redemption, private stats, demo excluded';
end $$;
rollback;
